/// <summary>
/// Finds the OMGMessageTypeTable record based in the type id.
/// </summary>
/// <param name = "_typeId">The type id</param>
/// <param name = "_forUpdate">Should the record be selected for update?</param>
/// <returns>The OMGMessageTypeTable record</returns>
public static OMGMessageTypeTable find(OMGMessageTypeId _typeId, boolean _forUpdate = false)
{
    OMGMessageTypeTable typeTable;

    typeTable.selectForUpdate(_forUpdate);

    if (_typeId)
    {
        select firstonly typeTable
            where typeTable.MessageTypeId == _typeId;
    }

    return typeTable;
}

/// <summary>
/// Validates that all is ok
/// </summary>
/// <returns>True if all is ok</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if (ret)
    {
        ret = this.validateClasses();

        if (this.InboundMessageHandlerClass && !this.Company)
        {
            ret = checkFailed("@OMG:CompanyMissingCheck");
        }
    }

    return ret;
}

public boolean validateClasses()
{
    boolean     ret = true;
    DictClass   dictClass;
    ;

    if (this.InboundMessageTransportClass)
    {
        dictClass = new DictClass(className2Id(this.InboundMessageTransportClass));
        if (!dictClass)
        {
            ret = checkFailed(strFmt("@OMG:InboundTransportClassDoesNotExist", this.InboundMessageTransportClass));
        }
    }

    if (this.InboundMessageHandlerClass)
    {
        dictClass = new DictClass(className2Id(this.InboundMessageHandlerClass));
        if (!dictClass)
        {
            ret = checkFailed(strFmt("@OMG:InboundHandlerClassDoesNotExist", this.InboundMessageHandlerClass));
        }
    }

    if (this.OutboundMessageTransportClass)
    {
        dictClass = new DictClass(className2Id(this.OutboundMessageTransportClass));
        if (!dictClass)
        {
            ret = checkFailed(strFmt("@OMG:OutboundTransportClassDoesNotExist", this.OutboundMessageTransportClass));
        }
    }
    return ret;
}

public static Object getDeserializedParameterContract(ClassId                           _transportClassId,
                                                      OMGSerializedParameterContract    _serializedContract)
{
    Object          dataContractClass;
    Object          transportHandlerObject;
    SysDictClass    sysDictTransportClass   = new SysDictClass(_transportClassId);
    MethodName      dataContractMethodName  = 'dataContractClass';
    ClassId         dataContractClassId;
    SysDictClass    sysDictDataContractClass;
    ;

    if (sysDictTransportClass)
    {
        transportHandlerObject = sysDictTransportClass.makeObject();

        if (sysDictTransportClass.hasObjectMethod(dataContractMethodName))
        {
            dataContractClassId         = sysDictTransportClass.callObject(dataContractMethodName, transportHandlerObject);
            sysDictDataContractClass    = new SysDictClass(dataContractClassId);
            dataContractClass           = FormJsonSerializer::deserializeObject(dataContractClassId, _serializedContract);
        }
    }

    return dataContractClass;
}

public static OMGCodePage getInboundCodePage(OMGMessageTypeId   _messageTypeId)
{        
    OMGCodePage             codePage;
    OMGMessageTypeTable     messageTypeTable = OMGMessageTypeTable::find(_messageTypeId);
    ;

    if (messageTypeTable && messageTypeTable.InboundMessageTransportClass)
    {
        Object  parameterContract = OMGMessageTypeTable::getDeserializedParameterContract(className2Id(messageTypeTable.InboundMessageTransportClass),
                                                                                          messageTypeTable.InboundSerializedParameterContract);
        if (parameterContract)
        {
            codePage = parameterContract.parmCodePage();
        }
    }

    return codePage;
}

/// <summary>
/// Modified field code
/// </summary>
/// <param name = "_fieldId">The field in question</param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(OMGMessageTypeTable, InboundMessageTransportClass)    :
            this.InboundSerializedParameterContract = '';
            if (this.Active)
            {
                this.Active = NoYes::No;
                Info(strFmt("@OMG:MessageTypeDeActivated", this.MessageTypeId));
            }
            break;

        case fieldNum(OMGMessageTypeTable, OutboundMessageTransportClass)   :
            this.OutboundSerializedParameterContract = '';
            if (this.Active)
            {
                this.Active = NoYes::No;
                Info(strFmt("@OMG:MessageTypeDeActivated", this.MessageTypeId));
            }
            break;

        case fieldNum(OMGMessageTypeTable, Active)                          :
            if (this.Active == NoYes::Yes)
            {
                boolean     inboundOk       = this.validateDataContracts(this.InboundMessageTransportClass, this.InboundSerializedParameterContract);
                boolean     outboundOk      = this.validateDataContracts(this.OutboundMessageTransportClass, this.OutboundSerializedParameterContract);
                boolean     processingOk    = this.validateDataContracts(this.InboundMessageHandlerClass, this.InboundSerializedHandlerContract);

                if (!inboundOk || !outboundOk || !processingOk)
                {
                    this.Active = NoYes::No;
                }
            }

    }
}

public boolean validateDataContracts(ClassName                      _className,
                                     OMGSerializedParameterContract _serializedParameterContract)
{
    boolean         ret = true;
    Object          dataContract;
    SysDictClass    sysDictDataContractClass;
    SysDictClass    sysDictClass;
    CompanyId       validationCompany;
    ;

    if (_className && this.getDataContractClassId(className2Id(_className)))
    {
        dataContract = OMGMessageTypeTable::getDeserializedParameterContract(className2Id(_className), _serializedParameterContract);

        if (!dataContract)
        {
            // Creating a blank data contract to be able to call validate
            sysDictDataContractClass    = new SysDictClass(this.getDataContractClassId(className2Id(_className)));
            dataContract                = sysDictDataContractClass.makeObject();                
        }

        sysDictClass = new SysDictClass(classIdGet(dataContract));

        if (sysDictClass.hasObjectMethod('parmContractDataAreaId'))
        {
            validationCompany = dataContract.parmContractDataAreaId();
        }

        validationCompany = validationCompany ? validationCompany : curExt();

        if (dataContract && sysDictClass.hasObjectMethod('validate'))
        {
            setPrefix(strFmt("@OMG:ValidatingParametersFor", _className));

            changecompany(validationCompany)
            {
                ret = dataContract.validate();
            }
        }
    }

    return ret;
}

public classId getDataContractClassId(ClassId   _transportClassId)
{
    SysDictClass    sysDictTransportClass   = new SysDictClass(_transportClassId);
    MethodName      dataContractMethodName  = 'dataContractClass';
    ClassId         dataContractClassId;
    ;

    if (sysDictTransportClass.hasObjectMethod(dataContractMethodName))
    {
        dataContractClassId         = sysDictTransportClass.callObject(dataContractMethodName, sysDictTransportClass.makeObject());
    }

    return dataContractClassId;
}
